exam_text.ro:
- Protocolul folosește delimitatori STX/ETX pentru sincronizare și CRC pentru integritate.
- LCD-ul este legat la stdout prin funcție putchar.

Pseudocod logic comentat:
// MCU1: emițător temperatură pe UART
MCU1_setup()
{
    init_sensor_temperatura()
    init_UART()
}

MCU1_loop()
{
    adc = read_temperature_sensor()        // achiziție senzor
    temp = convert_adc_to_celsius(adc)     // conversie în mărime fizică

    data = temp                            // payload-ul pachetului
    crc = CMD_TEMP XOR data                // verificare simplă

    UART_send(STX)                         // început cadru
    UART_send(CMD_TEMP)                    // comandă: temperatură
    UART_send(data)                        // valoarea măsurată
    UART_send(crc)                         // control erori
    UART_send(ETX)                         // sfârșit cadru

    wait(100 ms)
}

// MCU2: receptor + LCD
MCU2_setup()
{
    init_UART()
    init_LCD()
    redirect_STDIO_to_LCD()                // printf scrie pe LCD
}

MCU2_loop()
{
    byte = UART_read()

    if (byte == STX)                       // sincronizare cadru
    {
        cmd  = UART_read()
        data = UART_read()
        crc  = UART_read()
        etx  = UART_read()

        if (etx != ETX)
            LCD_print("FRAME ERR")
        else if (crc != (cmd XOR data))
            LCD_print("CRC ERR")
        else if (cmd == CMD_TEMP)
            LCD_print("T = ", data, " C")
    }
}

exam_text.en:
- The protocol uses STX/ETX delimiters for synchronization and CRC for integrity.
- The LCD is connected to stdout through a putchar function.

