exam_text.ro:
- Pe I2C se recomandă GND comun și rezistențe pull-up pe SDA/SCL.
- MCU2 validează CRC înainte de afișare.

Pseudocod logic comentat:
// MCU1: master I2C, citește umiditatea
MCU1_setup()
{
    init_humidity_sensor()
    init_I2C_master()
}

MCU1_loop()
{
    hum = read_humidity_sensor()           // valoarea de transmis
    data = hum
    crc = CMD_HUM XOR data

    I2C_start(address_MCU2)                // selectez receptorul
    I2C_write(CMD_HUM)
    I2C_write(data)
    I2C_write(crc)
    I2C_stop()

    wait(100 ms)
}

// MCU2: slave I2C + LCD
MCU2_setup()
{
    init_I2C_slave(address_MCU2)
    init_LCD()
    redirect_STDIO_to_LCD()
}

on_I2C_receive()
{
    cmd  = I2C_read()
    data = I2C_read()
    crc  = I2C_read()

    if (crc == (cmd XOR data) && cmd == CMD_HUM)
    {
        humidity = data                    // accept doar mesaj valid
        LCD_print("H = ", humidity, " %")
    }
    else
    {
        LCD_print("I2C CRC ERR")
    }
}

exam_text.en:
