exam_text.ro:
- Histerezisul impune \(TH_{ON} < TH_{OFF}\).
- Pragurile se pot modifica din terminal fără recompilare.

Pseudocod logic comentat:
setup()
{
    init_serial_STDIO()
    init_motor_driver()
    init_LCD()

    th_on  = default_low_threshold
    th_off = default_high_threshold
    motor = OFF
}

loop()
{
    if (Serial_available())                // praguri configurabile
    {
        th_on  = Serial_read_number()
        th_off = Serial_read_number()
    }

    value = read_sensor_feedback()

    // Histerezis: starea precedentă contează
    if (motor == OFF && value < th_on)
        motor = ON

    if (motor == ON && value > th_off)
        motor = OFF

    write_motor_driver(motor)

    LCD_print("Val=", value)
    LCD_print("M=", motor, " ON=", th_on, " OFF=", th_off)

    wait(50 ms)
}

