exam_text.ro:
- Temperatura peste prag produce simptom, dar motorul se oprește doar după calificare temporală.
- Resetarea protecției se face cu histerezis.

Pseudocod logic comentat:
setup()
{
    init_temperature_sensor()
    init_potentiometer()
    init_motor_driver()
    init_serial_STDIO()

    motor = ON
    error_counter = 0
    diagnostic = OK
}

loop()
{
    temp = read_motor_temperature()
    pot = read_ADC(POT)
    critical_limit = map_pot_to_temperature_limit(pot)

    // Detecție simptom: temperatură peste prag
    if (temp > critical_limit)
        overtemp_symptom = TRUE
    else
        overtemp_symptom = FALSE

    // Calificare: simptomul trebuie să persiste
    if (overtemp_symptom == TRUE)
        error_counter = error_counter + 1
    else
        error_counter = 0

    // Reacție de protecție
    if (error_counter >= qualification_limit)
    {
        diagnostic = OVERTEMP
        motor = OFF
    }

    // Revenire cu histerezis
    if (temp < critical_limit - hysteresis)
    {
        diagnostic = OK
        motor = ON
    }

    write_motor_driver(motor)
    Serial_print("T=", temp, " Motor=", motor, " Diag=", diagnostic)
}

