{
    R = read_user_red_value()
    G = read_user_green_value()
    B = read_user_blue_value()

    crc = CMD_RGB XOR R XOR G XOR B

    UART_send(STX)
    UART_send(CMD_RGB)
    UART_send(R)
    UART_send(G)
    UART_send(B)
    UART_send(crc)
    UART_send(ETX)
}

// MCU actuator: primește și aplică PWM
MCU_RGB_setup()
{
    init_UART()
    init_PWM_for_RGB_LED()
    init_serial_STDIO()
}

