{
    if (UART_read() == STX)
    {
        cmd = UART_read()
        R   = UART_read()
        G   = UART_read()
        B   = UART_read()
        crc = UART_read()
        etx = UART_read()

        if (etx == ETX && crc == (cmd XOR R XOR G XOR B) && cmd == CMD_RGB)
        {
            set_PWM(RED,   R)              // duty-cycle roșu
            set_PWM(GREEN, G)              // duty-cycle verde
            set_PWM(BLUE,  B)              // duty-cycle albastru
            Serial_print("RGB OK")
        }
        else
        {
            keep_old_PWM_values()
            Serial_print("RGB ERR")
        }
    }
}

