exam_text.ro:
- FreeRTOS separă achiziția, LCD și raportarea serială în taskuri independente.
- Queue-ul elimină accesul nesincronizat la date.

Pseudocod logic comentat:
main()
{
    create_queue(sensor_queue)

    create_task(Task_Acquisition, priority_high)
    create_task(Task_LCD,         priority_medium)
    create_task(Task_Serial,      priority_low)

    start_scheduler()
}

Task_Acquisition()
{
    loop_forever
    {
        value = read_sensor()              // achiziție periodică
        send_queue(sensor_queue, value)    // transmitere sigură între taskuri
        delay_until_next_period(50 ms)
    }
}

Task_LCD()
{
    loop_forever
    {
        if (receive_queue(sensor_queue, value))
            LCD_print("Val = ", value)
    }
}

Task_Serial()
{
    loop_forever
    {
        Serial_print("System running")
        delay_until_next_period(500 ms)
    }
}

