        value = read_sensor()              // periodic acquisition
        send_queue(sensor_queue, value)    // safe transfer between tasks
        delay_until_next_period(50 ms)
    }
}

Task_LCD()
{
    loop_forever
    {
        if (receive_queue(sensor_queue, value))
            LCD_print("Val = ", value)
    }
}

Task_Serial()
{
    loop_forever
    {
        Serial_print("System running")
        delay_until_next_period(500 ms)
    }
}
